local util = require("util")

-- The melta turret's art, generated by graphics/_blender/ (melta_render.py builds
-- and renders the model, assemble.py turns the renders into these sheets). Nothing
-- here is hand-drawn, so the numbers below must match what those scripts emit --
-- graphics/_blender/README.md records the contract.
--
-- Head (the rotating cannon):
--   256 x 256 frame, 64 directions, 1 frame each, line_length 1
--   8 files with 8 rows each -> 256 x 2048 per file (power of two both ways)
--   pivot is the frame centre, so shift is zero and the gun cannot wobble
--   scale 0.5 -> 128 px on screen per frame = 4 tiles, i.e. Factorio's 2x density
--
-- Base (the static emplacement) is a single 256 x 256 sprite at the same scale,
-- with its cast shadow baked in (melta-turret-base.png).
local FRAME = 256
local HEAD_FILES = 8
local ROWS_PER_FILE = 8

local head =
{
  width = FRAME,
  height = FRAME,
  frame_count = 1,
  direction_count = 64,
  line_length = 1,
  lines_per_file = ROWS_PER_FILE,
  slice = 1,
  scale = 0.5,
  shift = {0, 0},
  mipmap_count = 4,
  priority = "medium",
  filenames = {}
}

for i = 1, HEAD_FILES do
  head.filenames[i] = "__lilys-melta__/graphics/entity/melta-turret/melta-turret-head-" .. i .. ".png"
end

local function head_layers()
  return {layers = {table.deepcopy(head)}}
end

local base =
{
  filename = "__lilys-melta__/graphics/entity/melta-turret/melta-turret-base.png",
  width = FRAME,
  height = FRAME,
  frame_count = 1,
  scale = 0.5,
  shift = {0, 0},
  mipmap_count = 4,
  priority = "high"
}

-- Pipe stubs -----------------------------------------------------------------
-- Copied from lilys-cubeine's combustion center (prototypes/fuel/
-- cubeine-combustion-center.lua), which is the one place this look is already
-- right: space-age's electromagnetic-plant pipe pictures, in their own colours,
-- drawn only on a side that actually has a pipe.
--
-- Three engine fields do the work, and they are the reason this replaced the
-- mod's own renders:
--   `pipe_picture`             = the stub drawn where a pipe arrives
--   `draw_only_when_connected` = draw it *only* then, so an unused side stays bare
--                                hull. The old build rendered a "cap" plate for
--                                unused sides and put it at the connection point;
--                                the hull never reaches that point, so every unused
--                                side showed a plate floating off the deck.
--   `secondary_draw_order`     = -1 draws the stub behind the hull, so its inboard
--                                half is hidden and only the part that pokes past
--                                the rim reads -- a pipe running into the housing.
-- Same models as cubeine, no tint: the hardware is the same grey metal as every
-- other pipe the player builds.
--
-- The art lives in space-age; a base-only install keeps vanilla's own pipe covers
-- (what the vanilla flamethrower turret uses) instead.
local pipe_pictures
local pipe_covers
if mods["space-age"] then
  pipe_pictures = require("__space-age__.prototypes.entity.electromagnetic-plant-pictures").pipe_pictures
else
  pipe_covers = pipecoverspictures()
end

return
{
  head = head,
  base = base,
  pipe_picture = pipe_pictures,
  pipe_covers = pipe_covers,

  attacking_animation = head_layers(),
  prepared_animation = head_layers(),
  preparing_animation = head_layers(),
  ending_attack_animation = head_layers(),
  -- no fold/unfold: the cannon is always deployed, which keeps the head a single
  -- sheet instead of an 18-frame deploy strip nothing else would reuse
  folded_animation = head_layers(),
  folding_animation = head_layers()
}
